/bin/bash -c "python - <<'PY'
import numpy as np
z=np.load('source_pixels.npz')['rgb']
for i in [0,5,10,15,20,21,22,24,30,40,50,60,70,80,95]:
 f=z[i].astype(int)
 r,g,b=f[...,0],f[...,1],f[...,2]
 masks={
 'red':(r>100)&(r>g*1.45)&(r>b*1.3)&(r-g>35),
 'veryred':(r>140)&(g<90)&(b<90),
 'darkred':(r>55)&(r>g*1.35)&(r>b*1.15)&(r-g>20),
 }
 print('frame',i)
 for k,m in masks.items():
  ys,xs=np.where(m)
  if len(xs): print(' ',k,len(xs),'bbox',xs.min(),ys.min(),xs.max(),ys.max(),'cent',xs.mean().round(1),ys.mean().round(1),'meanRGB',f[m].mean(0).round(1))
  else: print(' ',k,0)
PY"

